<?php require_once __DIR__.'/../includes/functions.php';require_admin();$pdo=db();$stats=[];foreach(['students'=>"SELECT COUNT(*) FROM users WHERE role='student'",'active'=>"SELECT COUNT(*) FROM users WHERE role='student' AND status='active'",'groups'=>'SELECT COUNT(*) FROM study_groups','reports'=>"SELECT COUNT(*) FROM reports WHERE status='Pending'",'requests'=>'SELECT COUNT(*) FROM study_requests','sessions'=>"SELECT COUNT(*) FROM study_sessions WHERE status='scheduled' AND session_date>=CURDATE()"] as $k=>$sql)$stats[$k]=$pdo->query($sql)->fetchColumn();$months=$pdo->query("SELECT DATE_FORMAT(created_at,'%b %Y') label,COUNT(*) total FROM users WHERE role='student' AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY YEAR(created_at),MONTH(created_at) ORDER BY MIN(created_at)")->fetchAll();$popular=$pdo->query('SELECT s.name,COUNT(*) total FROM user_subjects x JOIN subjects s ON s.id=x.subject_id GROUP BY s.id ORDER BY total DESC LIMIT 6')->fetchAll();page_start('Admin dashboard',true); ?><div class="row g-3 mb-4"><?php foreach(['Total students'=>'students','Active students'=>'active','Study groups'=>'groups','Pending reports'=>'reports','Total requests'=>'requests','Upcoming sessions'=>'sessions'] as $label=>$key): ?><div class="col-6 col-lg-4 col-xl-2"><div class="card"><div class="card-body"><div class="text-secondary small"><?= e($label) ?></div><div class="stat"><?= (int)$stats[$key] ?></div></div></div></div><?php endforeach ?></div><div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-body"><h2 class="h5">Student registrations</h2><canvas id="chart" height="150"></canvas></div></div></div><div class="col-lg-5"><div class="card"><div class="card-body"><h2 class="h5">Popular subjects</h2><?php foreach($popular as $r): ?><div class="d-flex justify-content-between border-top py-2"><span><?= e($r['name']) ?></span><strong><?= $r['total'] ?></strong></div><?php endforeach ?></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById('chart'),{type:'bar',data:{labels:<?= json_encode(array_column($months,'label')) ?>,datasets:[{label:'New students',data:<?= json_encode(array_column($months,'total')) ?>,backgroundColor:'#817bf0',borderRadius:8}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});</script><?php page_end(); ?>
